    const dir = row.path.split('/').slice(0, Math.max(level, 0)).join('/');
    if (!groups.has(dir)) {
      const group = {dir: dir || '.', files: 0, additions: 0, deletions: 0, size: 0, units: new Set()};
      groups.set(dir, group); out.push(group);
